ALTER TABLE public.billing_accounts ADD COLUMN IF NOT EXISTS checkout_lock_token uuid;
ALTER TABLE public.account_data ADD COLUMN IF NOT EXISTS revision bigint NOT NULL DEFAULT 0;
ALTER TABLE public.subscriptions ADD CONSTRAINT subscriptions_profile_owner FOREIGN KEY(user_id) REFERENCES public.profiles(id) ON DELETE CASCADE NOT VALID;
CREATE TABLE public.payment_locks (subscription_id text NOT NULL, environment text NOT NULL, token uuid NOT NULL, expires_at timestamptz NOT NULL, PRIMARY KEY(subscription_id,environment));
GRANT ALL ON public.payment_locks TO service_role;
ALTER TABLE public.payment_locks ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.billing_configuration (environment text PRIMARY KEY, portal_configuration_id text NOT NULL);
GRANT ALL ON public.billing_configuration TO service_role;
ALTER TABLE public.billing_configuration ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.claim_billing_operation(p_user uuid,p_env text,p_token uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.billing_accounts(user_id,environment) VALUES(p_user,p_env) ON CONFLICT DO NOTHING; UPDATE public.billing_accounts SET checkout_lock_until=now()+interval '3 minutes',checkout_lock_token=p_token WHERE user_id=p_user AND environment=p_env AND NOT deleting AND (checkout_lock_until IS NULL OR checkout_lock_until<now()); RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.claim_billing_operation(uuid,text,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_billing_operation(uuid,text,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.claim_payment_event(p_subscription text,p_env text,p_token uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.payment_locks(subscription_id,environment,token,expires_at) VALUES(p_subscription,p_env,p_token,now()+interval '3 minutes') ON CONFLICT(subscription_id,environment) DO UPDATE SET token=excluded.token,expires_at=excluded.expires_at WHERE public.payment_locks.expires_at<now(); RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.claim_payment_event(text,text,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_payment_event(text,text,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.commit_subscription_event(p_event text,p_env text,p_token uuid,p_row jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.subscriptions; BEGIN r:=jsonb_populate_record(NULL::public.subscriptions,p_row); IF NOT EXISTS(SELECT 1 FROM public.payment_locks WHERE subscription_id=r.stripe_subscription_id AND environment=p_env AND token=p_token AND expires_at>now()) THEN RAISE EXCEPTION 'Payment lease expired'; END IF; IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=r.user_id) THEN RETURN false; END IF; INSERT INTO public.subscriptions(user_id,stripe_subscription_id,stripe_customer_id,product_id,price_id,status,current_period_start,current_period_end,ended_at,cancel_at_period_end,environment,updated_at) VALUES(r.user_id,r.stripe_subscription_id,r.stripe_customer_id,r.product_id,r.price_id,r.status,r.current_period_start,r.current_period_end,r.ended_at,r.cancel_at_period_end,p_env,now()) ON CONFLICT(stripe_subscription_id) DO UPDATE SET status=excluded.status,price_id=excluded.price_id,product_id=excluded.product_id,current_period_start=excluded.current_period_start,current_period_end=excluded.current_period_end,ended_at=excluded.ended_at,cancel_at_period_end=excluded.cancel_at_period_end,updated_at=now(); INSERT INTO public.billing_accounts(user_id,environment,customer_id,trial_used) VALUES(r.user_id,p_env,r.stripe_customer_id,true) ON CONFLICT(user_id,environment) DO UPDATE SET trial_used=true,customer_id=excluded.customer_id; INSERT INTO public.payment_events(id,environment) VALUES(p_event,p_env) ON CONFLICT DO NOTHING; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.commit_subscription_event(text,text,uuid,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.commit_subscription_event(text,text,uuid,jsonb) TO service_role;
CREATE OR REPLACE FUNCTION public.save_account_data(p_revision bigint,p_payload jsonb) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE next_revision bigint; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; INSERT INTO public.account_data(user_id,payload,revision) VALUES(auth.uid(),p_payload,1) ON CONFLICT(user_id) DO UPDATE SET payload=excluded.payload,revision=public.account_data.revision+1,updated_at=now() WHERE public.account_data.revision=p_revision RETURNING revision INTO next_revision; IF next_revision IS NULL THEN RAISE EXCEPTION 'SYNC_CONFLICT'; END IF; RETURN next_revision; END $$;
REVOKE ALL ON FUNCTION public.save_account_data(bigint,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_account_data(bigint,jsonb) TO authenticated;
REVOKE INSERT,UPDATE ON public.account_data FROM authenticated;
CREATE OR REPLACE FUNCTION public.finalize_generation(p_user uuid,p_env text,p_reservation uuid,p_success boolean,p_premium boolean) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.generation_usage SET last_success_at=CASE WHEN p_success AND NOT p_premium THEN now() ELSE last_success_at END,reservation_id=NULL,reserved_until=NULL WHERE user_id=p_user AND environment=p_env AND reservation_id=p_reservation AND reserved_until>now(); RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.finalize_generation(uuid,text,uuid,boolean,boolean) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.finalize_generation(uuid,text,uuid,boolean,boolean) TO service_role;